# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SAHABE KAVRAMI VE ASR-I SAADETTE ÖNE ÇIKAN SAHABE GRUPLARI</text>\n  <rect x="25" y="48" width="315" height="192" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">SAHABİ OLMANIN ÜÇ TEMEL ŞARTI</text>\n  <text x="40" y="98" font-size="11" fill="#1e3a8a">1. Hz. Peygamber (s.a.v.) döneminde yaşamak</text>\n  <text x="40" y="124" font-size="11" fill="#1e3a8a">2. Mümin olarak Hz. Peygamber\'i görmek veya</text>\n  <text x="50" y="140" font-size="11" fill="#1e3a8a">O\'nun meclisinde/sohbetinde bulunmak</text>\n  <text x="40" y="166" font-size="11" fill="#1e3a8a">3. İman üzere (Müslüman olarak) vefat etmek</text>\n  <rect x="40" y="186" width="285" height="38" rx="6" fill="#eff6ff" stroke="#60a5fa"/>\n  <text x="182" y="209" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Sahabeyi gören nesil: Tâbiîn | Sonraki: Tebeu\'t-Tâbiîn</text>\n  <rect x="360" y="48" width="315" height="192" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">ÖNCÜ SAHABE GRUPLARI</text>\n  <text x="375" y="96" font-size="11" fill="#14532d">• <tspan font-weight="bold">Sâbikûn-u Evvelûn:</tspan> İlk Müslüman olan öncüler</text>\n  <text x="375" y="118" font-size="11" fill="#14532d">• <tspan font-weight="bold">Muhacirler:</tspan> Mekke\'den hicret eden müminler</text>\n  <text x="375" y="140" font-size="11" fill="#14532d">• <tspan font-weight="bold">Ensar:</tspan> Medine\'de yardım eden ev sahipleri</text>\n  <text x="375" y="162" font-size="11" fill="#14532d">• <tspan font-weight="bold">Ashâb-ı Suffe:</tspan> Mescid-i Nebî\'deki ilim talebeleri</text>\n  <text x="375" y="184" font-size="11" fill="#14532d">• <tspan font-weight="bold">Aşere-i Mübeşşere:</tspan> Cennetle müjdelenen 10 sahabi</text>\n  <rect x="375" y="196" width="285" height="30" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="517" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Dua İfadesi: Radıyallahu anh / anhâ (r.a.)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KUR\'AN VE SÜNNETTE SAHABENİN FAZİLETİ</text>\n  <rect x="25" y="48" width="315" height="192" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">KUR\'AN-I KERİM\'DE SAHABE ÖVGÜSÜ</text>\n  <text x="40" y="98" font-size="11" fill="#78350f">• <tspan font-weight="bold">Tevbe, 100:</tspan> "Allah Muhacir ve Ensar\'dan</text>\n  <text x="48" y="114" font-size="11" fill="#78350f">razı olmuş, onlar da O\'ndan razı olmuştur."</text>\n  <text x="40" y="138" font-size="11" fill="#78350f">• <tspan font-weight="bold">Fetih, 18:</tspan> Bey\'atü\'r-Rıdvân (Ağaç altı biatı)</text>\n  <text x="40" y="162" font-size="11" fill="#78350f">• <tspan font-weight="bold">Fetih, 29:</tspan> Kendi aralarında merhametli, rükû</text>\n  <text x="48" y="178" font-size="11" fill="#78350f">ve secde ile Allah\'ın lütfunu arayan nesil</text>\n  <rect x="40" y="190" width="285" height="34" rx="6" fill="#ffffff" stroke="#fbbf24"/>\n  <text x="182" y="211" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Haşr, 8-9: Muhacir sadakati ve Ensar îsârı</text>\n  <rect x="360" y="48" width="315" height="192" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">HADİS-İ ŞERİFLERDE SAHABE SEVGİSİ</text>\n  <text x="375" y="98" font-size="11" fill="#581c87">• <tspan font-weight="bold">Hayru\'l-Kurûn:</tspan> "İnsanların en hayırlıları</text>\n  <text x="383" y="114" font-size="11" fill="#581c87">benim asrımda yaşayanlardır (sahabe)..."</text>\n  <text x="375" y="138" font-size="11" fill="#581c87">• <tspan font-weight="bold">İnfak Değeri:</tspan> Zor zamanda yapılan az infak,</text>\n  <text x="383" y="154" font-size="11" fill="#581c87">sonradan verilen Uhud Dağı altından üstündür.</text>\n  <text x="375" y="178" font-size="11" fill="#581c87">• <tspan font-weight="bold">Sevgi Ölçütü:</tspan> "Onları sevmek beni sevmektir."</text>\n  <rect x="375" y="190" width="285" height="34" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="517" y="211" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">Sahabeye hürmet, sünnete hürmetin gereğidir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SAHABENİN İSLAM MEDENİYETİNDEKİ ÜÇ TEMEL MİSYONU</text>\n  <rect x="25" y="48" width="205" height="190" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="127" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. Vahiy ve Sünneti Koruma</text>\n  <text x="40" y="98" font-size="11" fill="#1e3a8a">• Vahiy kâtipliği ve hafızlık</text>\n  <text x="40" y="120" font-size="11" fill="#1e3a8a">• Kur\'an\'ın Mushaf hâline</text>\n  <text x="48" y="136" font-size="11" fill="#1e3a8a">getirilmesi ve çoğaltılması</text>\n  <text x="40" y="160" font-size="11" fill="#1e3a8a">• Hadis-i şeriflerin titizlikle</text>\n  <text x="48" y="176" font-size="11" fill="#1e3a8a">ezberlenip rivayet edilmesi</text>\n  <rect x="40" y="190" width="175" height="34" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="127" y="211" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Emaneti Eksiksiz Aktarım</text>\n  <rect x="247" y="48" width="205" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="349" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">2. İlim ve Eğitim (İrşat)</text>\n  <text x="262" y="98" font-size="11" fill="#14532d">• Ashâb-ı Suffe mektebi</text>\n  <text x="262" y="120" font-size="11" fill="#14532d">• Muâz bin Cebel\'in Yemen\'e,</text>\n  <text x="270" y="136" font-size="11" fill="#14532d">Mus\'ab bin Umeyr\'in</text>\n  <text x="270" y="152" font-size="11" fill="#14532d">Medine\'ye muallim gitmesi</text>\n  <text x="262" y="176" font-size="11" fill="#14532d">• Tefsir ve fıkıh mektepleri</text>\n  <rect x="262" y="190" width="175" height="34" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="349" y="211" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Tâbiîn Neslini Yetiştirme</text>\n  <rect x="470" y="48" width="205" height="190" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="572" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">3. Temsil ve Tebliğ</text>\n  <text x="485" y="98" font-size="11" fill="#7f1d1d">• İslam ahlakını bizzat</text>\n  <text x="493" y="114" font-size="11" fill="#7f1d1d">yaşayarak örnek olma</text>\n  <text x="485" y="138" font-size="11" fill="#7f1d1d">• Şam, Mısır, Irak, Horasan</text>\n  <text x="493" y="154" font-size="11" fill="#7f1d1d">ve İstanbul önlerine (Eyüp</text>\n  <text x="493" y="170" font-size="11" fill="#7f1d1d">Sultan) kadar tebliğ</text>\n  <rect x="485" y="190" width="175" height="34" rx="6" fill="#ffffff" stroke="#f87171"/>\n  <text x="572" y="211" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">Canlı Kur\'an ve Sünnet Modeli</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
